node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const code=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const W=rd("app/(main)/spaces/[slug]/(profile)/community/page.tsx")
if(W===null)fail("the Space Community wall is gone, so the Space has no conversation")
if(!/<CommunityWallFeed[\s/>]/.test(code(W)))fail("the Community page no longer renders the wall feed, which is the whole substance of this row")
const R=rd("components/spaces/community-wall-feed.tsx")
if(R===null||code(R).indexOf("space_wall_feed")<0)fail("the wall feed no longer reads space_wall_feed, the gated reader")
const N=rd("lib/spaces/profile-nav.ts")
if(N===null||!/label: .Community./.test(code(N)))fail("the Space menu has no Community row, so the conversation has no door")
const F=rd("app/(main)/spaces/[slug]/(profile)/discussion/page.tsx")
if(F===null)fail("the discussion segment is gone: a reserved slug already sent out in notifications would 404")
console.log("LIVE-421 ok")'
